//! Every unit card's preset excerpts (`assets/units/sounds/`): generated by
//! `cargo run --release -p cantus-ui --example render_unit_sounds -- web` (round 37,
//! ADR 0101), rendered by Cantus on what its preset browser plays them on, at the
//! presets' own levels, with no processing after. Do not edit by hand.

/// One excerpt: its file (without `.mp3`), the preset's name and what it is for, each
/// `(English, Spanish)`.
pub struct Sound {
    pub file: &'static str,
    pub name: (&'static str, &'static str),
    pub what: (&'static str, &'static str),
    /// An effect's dry source (`SOURCES`); empty for an instrument.
    pub on: &'static str,
}

